import json
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path

BASE = 'http://localhost:8080'
START = datetime(2025, 3, 1, tzinfo=timezone.utc)
END = datetime(2025, 6, 1, tzinfo=timezone.utc)
token = None

def get_token():
    global token
    while True:
        try:
            with urllib.request.urlopen(urllib.request.Request(BASE + '/token', method='POST'), timeout=30) as r:
                token = [REDACTED_SECRET]'token']
                return
        except urllib.error.HTTPError as e:
            if e.code == 429:
                wait(e)
            else:
                raise
        except (urllib.error.URLError, TimeoutError):
            time.sleep(2)

def wait(e):
    body = e.read()
    try:
        info = json.loads(body)
    except ValueError:
        info = {}
    delay = e.headers.get('Retry-After') or info.get('retry_after') or info.get('retry_after_seconds')
    if delay is None:
        raise RuntimeError(f'429 without delay: {body"'!r}'"')
    print(f'rate limited: sleeping {delay}s', flush=True)
    time.sleep(float(delay) + 0.05)

def get(path):
    global token
    while True:
        if token is None:
            get_token()
        try:
            req = urllib.request.Request(BASE + path, headers={'Authorization': 'Bearer ' + token})
            with urllib.request.urlopen(req, timeout=30) as r:
                return json.load(r)
        except urllib.error.HTTPError as e:
            if e.code == 401:
                e.read()
                token = None
            elif e.code == 429:
                wait(e)
            elif e.code >= 500:
                print(f'{path}: HTTP {e.code}, retrying', flush=True)
                e.read()
                time.sleep(2)
            else:
                raise
        except (urllib.error.URLError, TimeoutError) as e:
            print(f'{path}: {e}, retrying', flush=True)
            time.sleep(2)

seen = set()
qualifying = []
duplicates = 0
page = 1
total_pages = None
while True:
    data = get(f'/orders?page={page}')
    assert data['page'] == page, (page, data['page'])
    if total_pages is None:
        total_pages = data['total_pages']
    assert data['total_pages'] == total_pages
    for order in data['items']:
        oid = order['id']
        if oid in seen:
            duplicates += 1
            continue
        seen.add(oid)
        placed = datetime.fromisoformat(order['placed_at'].replace('Z', '+00:00')).astimezone(timezone.utc)
        if order['status'] == 'shipped' and START <= placed < END:
            qualifying.append(order)
    print(f'orders page {page}/{total_pages}: {len(seen)} distinct, {duplicates} duplicates', flush=True)
    if data['next'] is None:
        assert page == total_pages
        break
    assert data['next'] == f'/orders?page={page + 1}', data['next']
    page += 1

customers = {}
regions = {k: 0 for k in ('north', 'south', 'east', 'west')}
for i, order in enumerate(qualifying, 1):
    cid = order['customer_id']
    if cid not in customers:
        customer = get('/customers/' + cid)
        assert customer['id'] == cid
        customers[cid] = customer
    customer = customers[cid]
    amount = (Decimal(order['amount_cents']) * (100 - customer['discount_pct']) / 100).quantize(Decimal('1'), rounding=ROUND_HALF_UP)
    regions[customer['region']] += int(amount)
    if i % 100 == 0:
        print(f'calculated {i}/{len(qualifying)} qualifying orders; {len(customers)} customers cached', flush=True)

result = {'total_cents': sum(regions.values()), 'order_count': len(qualifying), 'duplicates_skipped': duplicates, 'by_region': regions}
assert len({o['id'] for o in qualifying}) == len(qualifying)
assert set(result) == {'total_cents', 'order_count', 'duplicates_skipped', 'by_region'}
assert sum(regions.values()) == result['total_cents']
Path('/workspace/result.json').write_text(json.dumps(result, indent=2) + '\\n')
print(json.dumps(result, indent=2), flush=True)
print(f'distinct orders: {len(seen)}; customers fetched: {len(customers)}', flush=True)
